import{z as l,x as o,o as e,c as s,q as t,j as i,D as E,d as r,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"波动执行的专门问题","description":"","frontmatter":{"title":"波动执行的专门问题","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-vol-execution.md","filePath":"quant/ex-vol-execution.md","lastUpdated":1791413859000}'),d={name:"quant/ex-vol-execution.md"};function p(m,a,u,h,D,C){const B=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="波动执行的专门问题" tabindex="-1">波动执行的专门问题 <a class="header-anchor" href="#波动执行的专门问题" aria-label="Permalink to &quot;波动执行的专门问题&quot;">​</a></h1><div class="epigraph"><p>波动不改变执行问题的形式，改变的是每一个参数：价差、深度、σ、相关性与所有人的风险厌恶同时跳变；体制切换不是扰动项，是执行算法的第一等公民。</p><footer>—— 据 Brunnermeier and Pedersen, Market Liquidity and Funding Liquidity, Review of Financial Studies, 2009；Almgren and Chriss 对 σ 进入最优轨迹的论述整理</footer></div><p><a href="/quant/ex-auction-execution">上一课</a>在一次性出清里选申报点，现在回到连续时段，但让状态极端化。前面各课的公式都默认参数平稳：价差取均值、深度取均值、\\(\\sigma\\) 取预测值。恐慌日这些假设同时破裂，问题不是「换参数重算」，而是哪些环节该自动反应、哪些该冻结。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>σ 跳升沿四个通道改写执行。价差：逆向选择与做市库存分量同时走阔，见 <a href="/quant/spread-cost">买卖价差成本</a>，taker 起步成本翻倍。深度：报价撤走，<a href="/quant/toxic-flow">毒性流与停报价</a> 的机制——报价的期权价值随波动上升，撤单是做市商的理性反应。风险预算：VaR 类限额随 σ 收紧，等效 \\(\\lambda\\) 跳升，<a href="/quant/almgren-chriss">Almgren–Chriss 最优执行</a> 的 \\(\\kappa^2=\\lambda\\sigma^2/\\eta\\) 里分子两个因子同向放大。制度约束：涨跌停、熔断、临停截断可执行集，见 <a href="/quant/cn-limit-liquidity-hole">涨跌停与流动性黑洞</a>。四个通道时标不同：价差秒级、预算分钟级、熔断随机。</p><p><span class="marginnote">逆向选择就是「跟你交易的人可能知道你不知道的事」。波动跳升时这种风险变大，做市商挂单等于白送一份更贵的期权，所以理性反应是撤单或拉宽价差——报价撤走不是恐慌，是算账。</span></p><p>问题于是是：哪些参数允许在线重估，哪些必须事前冻结？恐慌中现场调参，等于把一次不可复制的样本写进生产系统。</p><h3 id="紧迫度的重推与参数的分层" tabindex="-1">紧迫度的重推与参数的分层 <a class="header-anchor" href="#紧迫度的重推与参数的分层" aria-label="Permalink to &quot;紧迫度的重推与参数的分层&quot;">​</a></h3><p>AC 的 \\(\\kappa\\) 在恐慌日的方向并不显然：\\(\\sigma\\) 与 \\(\\lambda\\) 上升推高 \\(\\kappa\\)（更前倾、更快卸风险），但 \\(\\eta\\)——每单位参与率的冲击——同样上升（深度变薄），压低 \\(\\kappa\\)。净方向不可先验断定，必须用当日的价差与深度重估 \\(\\eta\\) 再算。工程化做法分三层：外层是事件日历（财报、到期、宏观数据），事前收紧参与率上限与价格保护；中层是状态触发（价差、深度、波动超过阈值），触发预登记的参数切换，而不是临时调参；内层是调度与接口逻辑，保持不变以保证归因可比。冻结清单与切换清单都进规格文档。</p><p><span class="marginnote">参与率的分母在恐慌日失真：ADV 是常态样本的均值，而恐慌日的可成交深度可能只有常态的一两成。按常态 ADV 算出的 \\(q/\\mathrm{ADV}=5\\%\\)，真实瞬时参与率可能已是四成——分母要换算成当日已实现或盘口推算的深度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>价格保护：所有子单带限价围栏，相对中点或最近成交价留固定基点带，防止恐慌跳跃中市价子单吃穿数档；围栏触发不是重试信号，应上报并等待状态确认。接口切换：波动升高时从排队转向吃簿或转入 <a href="/quant/ex-auction-execution">竞价配额</a>，把无限等待换成有界成本；此时 <a href="/quant/ex-slice-scheduling-deep">子单调度的深化</a> 的毒性门控应已压低参与上限。熔断与临停：暂停期间的申报规则、复牌竞价的处理预置在状态机里。完成政策：恐慌日允许显式放弃并把余量计入机会成本，与投资端事先约定；强行完成会把尾部清扫做成最大的一笔冲击。</p>',12)),(e(),i(n,null,{default:E(()=>[A(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%7B%22%CF%83%20%E8%B7%B3%E5%8D%87%3F%22%7D%0A%20%20SIG%20--%3E%7C%E6%98%AF%7C%20EST%5B%22%E5%BD%93%E6%97%A5%E9%87%8D%E4%BC%B0%E4%BB%B7%E5%B7%AE%20%2F%20%E6%B7%B1%E5%BA%A6%20%2F%20%CE%B7%22%5D%0A%20%20SIG%20--%3E%7C%E5%90%A6%7C%20RUN%5B%22%E5%B8%B8%E8%A7%84%E8%B0%83%E5%BA%A6%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20EST%20--%3E%20COMP%7B%22%CE%BA%20%E5%87%80%E6%96%B9%E5%90%91%22%7D%0A%20%20COMP%20--%3E%7C%E9%A3%8E%E9%99%A9%E4%B8%BB%E5%AF%BC%7C%20FRONT%5B%22%E5%89%8D%E5%80%BE%3A%20%E5%8A%A0%E9%80%9F%E5%8D%B8%E9%A3%8E%E9%99%A9%22%5D%0A%20%20COMP%20--%3E%7C%E5%86%B2%E5%87%BB%E4%B8%BB%E5%AF%BC%7C%20SLOW%5B%22%E6%94%BE%E6%85%A2%3A%20%E5%8E%8B%E5%8F%82%E4%B8%8E%E4%B8%8A%E9%99%90%22%5D%0A%20%20CAL%5B%22%E4%BA%8B%E4%BB%B6%E6%97%A5%E5%8E%86%E4%B8%8E%E8%A7%A6%E5%8F%91%E9%98%88%E5%80%BC%22%5D%20--%3E%20SIG%0A%20%20FRONT%20--%3E%20GUARD%5B%22%E4%BB%B7%E6%A0%BC%E5%9B%B4%E6%A0%8F%20%2B%20%E5%AE%8C%E6%88%90%E6%94%BF%E7%AD%96%22%5D%0A%20%20SLOW%20--%3E%20GUARD%0A%20%20GUARD%20--%3E%20LOG%5B%22%E6%92%A4%E5%8D%95%E4%B8%8E%E5%88%87%E6%8D%A2%E7%95%99%E7%97%95%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步性是恐慌日执行成本的放大器。所有按风险预算运转的交易台在 σ 跳升时同时前倾，各自把他人当作外生流动性，合计冲击远超单账户模型；这是 <a href="/quant/arrival-price">到达价格算法</a> 拥挤问题的极端版。流动性螺旋补上第二级：价格下跌—资金压力—报价收缩，市场与资金流动性互相加强，见 <a href="/quant/liquidity-spiral-risk">流动性螺旋</a>；此时「等价差恢复」本身就是有风险的仓位。经销商 gamma 一类机制性流（<a href="/quant/dealer-gamma-regime">经销商正负 gamma 体制</a>）在特定价位制造方向可预判的对冲流，恐慌日与之重叠时条件 \\(\\eta\\) 离散度极大，点估计失去意义，应带分布进入调度。</p>',2)),(e(),i(n,null,{default:E(()=>[A(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20FUND%5B%22%E8%B5%84%E9%87%91%E5%8E%8B%E5%8A%9B%E4%B8%8A%E5%8D%87%3A%20%E4%BF%9D%E8%AF%81%E9%87%91%E8%BF%BD%E7%BC%B4%22%5D%0A%20%20FUND%20--%3E%20QUOTE%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E6%94%B6%E7%BC%A9%E6%8A%A5%E4%BB%B7%2C%20%E6%B7%B1%E5%BA%A6%E5%8F%98%E8%96%84%22%5D%0A%20%20QUOTE%20--%3E%20IMPACT%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%E5%8D%95%E9%87%8F%2C%20%E5%86%B2%E5%87%BB%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20IMPACT%20--%3E%20DROP%0A%20%20DROP%20--%3E%20DESK%5B%22%E5%90%84%E4%BA%A4%E6%98%93%E5%8F%B0%20%CF%83%20%E8%B7%B3%E5%8D%87%2C%20%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E5%90%8C%E6%AD%A5%E6%94%B6%E7%B4%A7%22%5D%0A%20%20DESK%20--%3E%20TILT%5B%22%E5%90%8C%E6%AD%A5%E5%89%8D%E5%80%BE%E6%8A%9B%E5%94%AE%2C%20%E4%BA%92%E7%9B%B8%E6%8A%8A%E5%AF%B9%E6%96%B9%E5%BD%93%E5%A4%96%E7%94%9F%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20TILT%20--%3E%20DROP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">流动性螺旋可以类比剧院里有人喊「着火了」：每个人都想先走，门口反而更挤。市场版是报价收缩让冲击变大、冲击变大让价格更差、价格更差让资金压力更大，一圈圈自我加强。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>校准于平静日的冲击系数与填成概率在恐慌日全部失效，历史回放对极端日的代表性有限，参数切换只能靠事前登记的规则而不是回测最优化。TCA 必须按波动体制分层，否则恐慌日的执行会污染全样本均值。合规上，恐慌日的撤单率与报撤比受监控，见 <a href="/quant/cn-fee-cancel-ratio">差异化收费与撤单率监控</a>，防御性撤单也要留痕可解释。最后是能力边界：执行算法能做的是不把恐慌变成自己的事故，不能把恐慌变成 alpha。</p><p><span class="marginnote">为什么极端日不能靠回测调参：样本里恐慌日只有寥寥几次，拟合出的冲击系数带着巨大估计误差，用它「最优化」切换规则等于把几次偶然写成规律。所以规则要事前登记，事后只验证不挑选。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恐慌日四个通道同时跳变：价差、深度、风险预算、制度约束，时标各不相同。</li><li>\\(\\kappa\\) 的净方向不可先验断定：\\(\\sigma,\\lambda\\) 推高、\\(\\eta\\) 压低，须用当日深度重估。</li><li>参数分三层管理：事件日历、预登记的状态触发、冻结的调度与接口逻辑。</li><li>全部子单带价格围栏；熔断与复牌竞价预置在状态机里；完成政策允许显式放弃。</li><li>同步前倾与流动性螺旋放大成本，条件 \\(\\eta\\) 应带分布而不是点估计。</li><li>TCA 按波动体制分层；恐慌日撤单留痕；执行的目标是不添乱，不是套利。</li><li>出处：Brunnermeier and Pedersen, <em>RFS</em>, 2009；Almgren and Chriss, <em>Journal of Risk</em>, 2000/2001；价差分解见经典微观结构文献。</li></ul>',6))])}const f=l(d,[["render",p]]);export{_ as __pageData,f as default};
